import hashlib, json
V2_DOMAIN_TAG = 'mycelium.action-ref:v2:'
def jcs(obj): return json.dumps(dict(sorted(obj.items())), separators=(',',':'), ensure_ascii=False).encode('utf-8')
def compute_action_ref_v1(payload): return hashlib.sha256(jcs(payload)).hexdigest()
def compute_action_ref_v2(payload): return 'v2:' + hashlib.sha256(V2_DOMAIN_TAG.encode('utf-8') + jcs(payload)).hexdigest()
